class IdempotencyGuard {
    private val mutex = Mutex()
    private val seen = mutableSetOf<String>()
    suspend fun claim(key: String): Boolean = mutex.withLock {
        if (key in seen) false else { seen += key; true }   // false => duplicate
    }
}

suspend fun onMessage(msg: Message) {
    if (!guard.claim(msg.idempotencyKey)) return ack(msg)    // duplicate: absorb
    applyEffects(msg); ack(msg)
}

