private val seen = ConcurrentHashMap<String, Long>()   // key -> expiry

fun claim(key: String, ttlMs: Long): Boolean =
    seen.putIfAbsent(key, System.currentTimeMillis() + ttlMs) == null

fun onMessage(msg: Message) {
    if (!claim(msg.idempotencyKey, REDELIVERY_WINDOW_MS)) return ack(msg)
